import{_ as t,o,c as a,ag as r}from"./chunks/framework.B7PviQjB.js";const s="/docs/images/collaborate/edit-together-peer-cursor.png",g=JSON.parse('{"title":"Edit together","description":"See who else is in a document, jump to where they are working, and check that your edits are saved.","frontmatter":{"title":"Edit together","description":"See who else is in a document, jump to where they are working, and check that your edits are saved.","type":"how-to"},"headers":[],"relativePath":"collaborate/edit-together.md","filePath":"collaborate/edit-together.md"}'),n={name:"collaborate/edit-together.md"};function i(h,e,d,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="edit-together" tabindex="-1">Edit together <a class="header-anchor" href="#edit-together" aria-label="Permalink to &quot;Edit together&quot;">​</a></h1><p>Several people can edit the same sheet, doc, presentation, note, or board at once, and everyone sees each change as it happens.</p><p>There is nothing to save or refresh. Anyone in the workspace can join, and so can anyone with an editor <a href="/docs/collaborate/share.html">share link</a>.</p><h2 id="see-who-is-here" tabindex="-1">See who is here <a class="header-anchor" href="#see-who-is-here" aria-label="Permalink to &quot;See who is here&quot;">​</a></h2><p>Everyone who has the document open appears as an avatar in the top right of the header. Up to four show at once; click <strong>+N</strong> to see the rest.</p><p>Each person also gets a color and a marker where they are working:</p><table tabindex="0"><thead><tr><th>Document</th><th>What you see</th></tr></thead><tbody><tr><td>Sheet</td><td>A colored outline on their selected cell, with their name</td></tr><tr><td>Doc and note</td><td>A colored text cursor with their name</td></tr><tr><td>Presentation and board</td><td>Their selection, and on a board their mouse pointer</td></tr><tr><td>PDF</td><td>Their avatar in the header</td></tr></tbody></table><p>In sheets and docs, the name fades a few seconds after the person stops moving. Hover their cursor to show it again. In notes, presentations, and boards the name stays on screen.</p><p>Signed-in people show their username. People on a share link who aren&#39;t signed in show as <strong>Anonymous</strong>.</p><p><img src="'+s+'" alt="Doc with a second person&#39;s colored cursor labeled Anonymous, and two avatars in the header"></p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>The header has no room for avatars on a phone, so they&#39;re hidden. Collaborators&#39; cursors and selections still appear in the document.</p><h2 id="jump-to-a-collaborator" tabindex="-1">Jump to a collaborator <a class="header-anchor" href="#jump-to-a-collaborator" aria-label="Permalink to &quot;Jump to a collaborator&quot;">​</a></h2><p>In sheets, docs, and boards, you can go to where someone is working.</p><ol><li>Hover an avatar in the header. In a sheet, the tooltip names their cell, for example <em>Click to jump to B4</em>.</li><li>Click the avatar.</li></ol><p>A sheet or doc scrolls to their position. On a board you start following them: your view moves with theirs, and a banner says <em>Following &lt;name&gt; — Esc to stop</em>. Press <code>Escape</code> to stop following.</p><p>You can&#39;t jump to yourself, or to someone whose position isn&#39;t known yet.</p><h2 id="rename-a-document" tabindex="-1">Rename a document <a class="header-anchor" href="#rename-a-document" aria-label="Permalink to &quot;Rename a document&quot;">​</a></h2><ol><li>Click the document&#39;s title in the header.</li><li>Type the new name.</li><li>Press <code>Enter</code> to save, or <code>Escape</code> to cancel.</li></ol><p>Everyone with the document open sees the new title right away. Any workspace member can rename a document.</p><h2 id="check-that-your-work-is-saved" tabindex="-1">Check that your work is saved <a class="header-anchor" href="#check-that-your-work-is-saved" aria-label="Permalink to &quot;Check that your work is saved&quot;">​</a></h2><p>A status chip next to the header buttons shows whether your edits have reached the server.</p><table tabindex="0"><thead><tr><th>Chip</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Saved</strong></td><td>Everything you did is on the server.</td></tr><tr><td><strong>Saving…</strong></td><td>Your latest changes are on their way.</td></tr><tr><td><strong>Reconnecting…</strong></td><td>The connection dropped, but nothing of yours is waiting.</td></tr><tr><td><strong>Not saved</strong></td><td>You have changes that haven&#39;t reached the server.</td></tr></tbody></table><p>Hover the chip for more detail. If <strong>Not saved</strong> lasts more than two seconds, a warning appears that says whether the connection dropped or the server rejected your changes. A <strong>Saved</strong> message appears when your work gets through. If the warning stays, see <a href="/docs/start/troubleshooting.html">Troubleshooting</a>.</p><p>While you have unsent changes, leaving the document asks <em>Leave without saving?</em> Click <strong>Stay</strong> to keep the tab open, or <strong>Leave</strong> to discard the changes.</p><div class="warning custom-block"><p class="custom-block-title">Wait for Saved before you close the tab</p><p>Unsent changes exist only in this browser tab. The browser doesn&#39;t always ask before closing, so a missing prompt doesn&#39;t mean your work is safe.</p></div><p>The chip appears in sheets, docs, presentations, notes, and boards, and on an editor share link. PDFs don&#39;t have one.</p><h3 id="on-a-phone-1" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone-1" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p><strong>Saved</strong> is hidden to save space, and the other states show as an icon only. The <strong>Not saved</strong> warning message still appears.</p><h2 id="edit-the-same-thing-at-the-same-time" tabindex="-1">Edit the same thing at the same time <a class="header-anchor" href="#edit-the-same-thing-at-the-same-time" aria-label="Permalink to &quot;Edit the same thing at the same time&quot;">​</a></h2><ul><li><strong>Sheets</strong>: when two people change the same cell, the last change wins.</li><li><strong>Docs and notes</strong>: text typed at the same time by two people is merged, so both people&#39;s words are kept.</li><li><strong>Presentations</strong>: text in a text box, shape, table cell, or speaker notes is saved when you click away. If two people edit the same box, the last one to click away wins. See <a href="/docs/slides/">Slides</a>.</li><li><strong>Boards</strong>: moving, resizing, and restyling follow the last change.</li></ul><p>You never see a conflict dialog. Watch for other people&#39;s cursors to avoid editing the same spot.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>A viewer share link can&#39;t edit, so it shows <strong>View only</strong> instead of the status chip.</li><li>Version history isn&#39;t available on share links. See <a href="/docs/collaborate/version-history.html">Version history</a>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/collaborate/share.html">Share a document</a> to invite someone to edit.</li><li><a href="/docs/collaborate/comments.html">Comments and mentions</a> to discuss changes.</li><li><a href="/docs/collaborate/version-history.html">Version history</a> to undo a collaborator&#39;s change.</li><li><a href="/docs/board/facilitate-a-session.html">Facilitate a session</a> for spotlight, cursor chat, and timers on a board.</li></ul>',36)])])}const u=t(n,[["render",i]]);export{g as __pageData,u as default};
